INSERT INTO `v1_dd2eff108733377029ba61a330a6bcba4f5d70243f32c6af60336e7a9c05b2c3` VALUES ("バトル開始時、すべてのモンスターの物理防御力をアップさせる。この効果は物理防御力ダウンの影響を受けない。", 10091003, "物理防御力（ダウン不可）アップ", 4100910, "boss_def_lower_limit");
INSERT INTO `v1_dd2eff108733377029ba61a330a6bcba4f5d70243f32c6af60336e7a9c05b2c3` VALUES ("バトル開始時、すべてのモンスターの魔法防御力をアップさせる。この効果は魔法防御力ダウンの影響を受けない。", 10091004, "魔法防御力（ダウン不可）アップ", 4100910, "boss_magic_def_lower_limit");
INSERT INTO `v1_dd2eff108733377029ba61a330a6bcba4f5d70243f32c6af60336e7a9c05b2c3` VALUES ("バトル開始時、すべてのモンスターがＴＰダウン\n75％カット状態になる。", 10091005, "ＴＰダウンカット", 4100910, "boss_tp_down_cut");
INSERT INTO `v1_dd2eff108733377029ba61a330a6bcba4f5d70243f32c6af60336e7a9c05b2c3` VALUES ("バトル開始時、すべてのキャラのＴＰ上昇をダウンさせる。", 10091006, "ＴＰ上昇ダウン", 4100910, 3);
